// Umbral de probabilidad de lluvia a monitorear (%)
const UMBRAL_PROBABILIDAD = 60;
const UBICACION = 'Viña del Mar, Chile';

const hourly = $input.first().json.hourly;
if (!hourly || !hourly.time || !hourly.precipitation_probability) {
  return [{ json: { alerta_activa: false, motivo: 'Sin datos horarios' } }];
}

// Obtener fecha y hora actual en zona local
const now = new Date();
const limite24h = new Date(now.getTime() + (24 * 60 * 60 * 1000));

let horasConLluvia = [];
let maxProbabilidad = 0;

for (let i = 0; i < hourly.time.length; i++) {
  const horaItem = new Date(hourly.time[i]);

  // Evaluar solo las próximas 24 horas a partir del momento de ejecución
  if (horaItem >= now && horaItem <= limite24h) {
    const prob = hourly.precipitation_probability[i] || 0;
    const prec = (hourly.precipitation && hourly.precipitation[i]) ? hourly.precipitation[i] : 0;

    if (prob > maxProbabilidad) {
      maxProbabilidad = prob;
    }

    if (prob >= UMBRAL_PROBABILIDAD) {
      horasConLluvia.push({
        hora: hourly.time[i],
        probabilidad: prob,
        precipitacion_mm: prec
      });
    }
  }
}

if (horasConLluvia.length > 0) {
  const primera = horasConLluvia[0];
  return [{
    json: {
      alerta_activa: true,
      ubicacion: UBICACION,
      umbral_configurado: UMBRAL_PROBABILIDAD,
      max_probabilidad: maxProbabilidad,
      primera_hora_lluvia: primera.hora,
      horas_afectadas: horasConLluvia.length,
      mensaje: `🌧️ Alerta de Lluvia: Se espera lluvia en ${UBICACION} a partir de las ${primera.hora.split('T')[1]} con una probabilidad máxima del ${maxProbabilidad}%.`
    }
  }];
} else {
  return [{
    json: {
      alerta_activa: false,
      ubicacion: UBICACION,
      max_probabilidad: maxProbabilidad,
      mensaje: `Condiciones estables en las próximas 24h (Probabilidad máx: ${maxProbabilidad}% debajo del umbral de ${UMBRAL_PROBABILIDAD}%).`
    }
  }];
}

